// function provided by FlorianUekermann
func good(set []uint64) (checksum uint) {
	for wordIdx, word := range set {
		wordIdx := uint(wordIdx * 64)
		for word != 0 {
			bitIdx := uint(bits.TrailingZeros64(word))
			word ^= 1 << bitIdx
			index := wordIdx + bitIdx
			checksum += index
		}
	}
	return checksum
}

